/* walkdemo — ARCADE-1 walking-spritesheet experiment.
 *
 * A 40x56 4-bit character walking left/right on flat ground at 60 fps.
 * The art is generated by tools/gen_walk_sheet.py (a PNG strip plus its
 * assets.json manifest) and compiled by tools/arc1_assetc.py into
 * walkdemo_sheet.h — hero refs plus the idle/walk ANIMATION TABLES
 * (Wave 3). The guest plays those tables with asset.h's anim_tick(),
 * timed by the frame timer (arcade1_timer_count: +1 per machine frame,
 * never host time), and draws with asset_sprite4() — no stride
 * arithmetic, no hand-rolled tick counter. Findings and measurements:
 * docs/experiments/walkdemo.md; the Wave-3 migration notes live in
 * docs/experiments/arc1-assetc.md.
 *
 * The four globals below are what the test reads back:
 *   arcade1 run walkdemo.arc1 --frames N --input script.txt \
 *       --syms walkdemo.syms --vars x,facing,anim,moving --capture f.ppm
 */
#include "asset.h"            /* sprite4_ref, asset_sprite4, anim_tick */
#include "walkdemo_sheet.h"   /* generated: hero refs + idle/walk tables */

#define SCREEN_W 480
#define SCREEN_H 270
#define GROUND_Y 200       /* the feet line the character stands on */
#define SPEED    2         /* px per frame */
#define MIN_X    4
#define MAX_X    (SCREEN_W - HERO_W - 4)

/* RGB565 components, spelled out so they are readable: (r5,g6,b5). */
#define SKY   ((4u << 11) | (12u << 5) | 28u)   /* dusk blue */
#define EDGE  ((12u << 11) | (48u << 5) | 16u)  /* ground edge highlight */
#define GRASS ((4u << 11) | (28u << 5) | 8u)    /* dark green */

int x = 20;       /* left edge of the character */
int facing = 0;   /* 0 = right, 1 = left (flip X, free in the blitter) */
int anim = 0;     /* sheet frame: 0 idle, 1..6 walk cycle */
int moving = 0;   /* 1 while a direction is held */

/* The two animations the manifest declares, played from the emitted
 * tables: the walk cycle ping-pongs through frames 1..6 (contact .. pass
 * .. back), the idle stands (one step). ANIM() sizes each table at
 * compile time; WALK_MS (67) is the old WALK_TICK = 4 frames at 60 fps. */
static anim_state walk = ANIM(walk_frames, WALK_MS, ANIM_PINGPONG);
static anim_state idle = ANIM(idle_frames, IDLE_MS, ANIM_LOOP);
static int was_moving;   /* previous frame's moving flag (for the step-off) */

static void upload_palette(void)
{
    int i;

    for (i = 0; i < 16; i++)
        arcade1_pal(hero_frames[0].bank * 16 + i, hero_palette[i]);
}

static void draw(const sprite4_ref *fr)
{
    arcade1_clear(SKY);
    arcade1_rect(0, GROUND_Y, SCREEN_W, 2, EDGE);
    arcade1_rect(0, GROUND_Y + 2, SCREEN_W, SCREEN_H - GROUND_Y - 2, GRASS);
    asset_sprite4(fr, x, GROUND_Y - fr->h + 2,
                  facing ? 1u : 0u);      /* flags bit0 = flip X */
    arcade1_present();
}

int main(void)
{
    upload_palette();

    for (;;) {
        unsigned pad = arcade1_pad();
        unsigned t = arcade1_timer_count();   /* +1 per machine frame */
        const sprite4_ref *fr;

        moving = 0;
        if (pad & BTN_RIGHT) { x += SPEED; facing = 0; moving = 1; }
        if (pad & BTN_LEFT)  { x -= SPEED; facing = 1; moving = 1; }
        if (x < MIN_X) x = MIN_X;
        if (x > MAX_X) x = MAX_X;

        if (moving) {
            if (!was_moving)
                anim_reset(&walk, t);     /* step off in the contact pose,
                                           * not 3 frames of idle pose */
            fr = anim_tick(&walk, t);
        } else {
            fr = anim_tick(&idle, t);     /* stand when nothing is held */
            anim_reset(&walk, t);         /* next step-off starts fresh */
        }
        was_moving = moving;
        anim = (int)(fr - hero_frames);   /* the sheet frame the test greps */

        draw(fr);
    }
}
